((select id from public.tracks where slug='ielts65'),'commute','đi lại (giữa nhà và nơi làm)','My daily commute takes about forty minutes by metro.','Quãng đường đi làm mỗi ngày của tôi mất khoảng bốn mươi phút bằng tàu điện.','trans','approved','SteelSpeak',0),
