((select id from public.tracks where slug='ielts65'),'traffic congestion','ùn tắc giao thông','Traffic congestion costs drivers hours every week.','Ùn tắc giao thông khiến tài xế mất hàng giờ mỗi tuần.','trans','approved','SteelSpeak',2),
