((select id from public.tracks where slug='ielts65'),'to have a detrimental effect on','gây ảnh hưởng xấu đến','Smoking has a detrimental effect on health.','Hút thuốc gây ảnh hưởng xấu đến sức khỏe.','soc','approved','SteelSpeak',122),
((select id from public.tracks where slug='ielts65'),'to contribute to society','đóng góp cho xã hội','Everyone can contribute to society in some way.','Ai cũng có thể đóng góp cho xã hội theo cách nào đó.','soc','approved','SteelSpeak',123),
((select id from public.tracks where slug='ielts65'),'nuclear family','gia đình hạt nhân','Nuclear families are more common in cities.','Gia đình hạt nhân phổ biến hơn ở thành phố.','soc','approved','SteelSpeak',124),
