((select id from public.tracks where slug='ielts65'),'to integrate into','hòa nhập vào','Immigrants need time to integrate into a new culture.','Người nhập cư cần thời gian hòa nhập văn hóa mới.','soc','approved','SteelSpeak',127),
((select id from public.tracks where slug='ielts65'),'On the one hand','Một mặt','On the one hand, cars offer convenience.','Một mặt, ô tô mang lại sự tiện lợi.','phr','approved','SteelSpeak',128),
