((select id from public.tracks where slug='ielts65'),'It is widely believed that','Nhiều người tin rằng','It is widely believed that technology improves our lives.','Nhiều người tin rằng công nghệ cải thiện cuộc sống.','phr','approved','SteelSpeak',130),
((select id from public.tracks where slug='ielts65'),'A case in point is','Một ví dụ điển hình là','A case in point is the growth of online banking.','Một ví dụ điển hình là sự phát triển của ngân hàng số.','phr','approved','SteelSpeak',131),
((select id from public.tracks where slug='ielts65'),'As a result','Do đó','As a result, many people now work from home.','Do đó, nhiều người giờ làm việc ở nhà.','phr','approved','SteelSpeak',132),
((select id from public.tracks where slug='ielts65'),'In contrast','Ngược lại','In contrast, rural areas have fewer jobs.','Ngược lại, nông thôn có ít việc làm hơn.','phr','approved','SteelSpeak',133),
((select id from public.tracks where slug='ielts65'),'To put it simply','Nói đơn giản thì','To put it simply, prevention is better than cure.','Nói đơn giản, phòng bệnh hơn chữa bệnh.','phr','approved','SteelSpeak',134),
((select id from public.tracks where slug='ielts65'),'There is no doubt that','Không nghi ngờ gì','There is no doubt that education changes lives.','Không nghi ngờ gì, giáo dục thay đổi cuộc đời.','phr','approved','SteelSpeak',135),
((select id from public.tracks where slug='ielts65'),'I would argue that','Tôi cho rằng','I would argue that public transport should be free.','Tôi cho rằng giao thông công cộng nên miễn phí.','phr','approved','SteelSpeak',136),
((select id from public.tracks where slug='ielts65'),'This is mainly because','Điều này chủ yếu là vì','This is mainly because prices have risen.','Điều này chủ yếu là vì giá cả tăng.','phr','approved','SteelSpeak',137),
((select id from public.tracks where slug='ielts65'),'To a certain extent','Ở một mức độ nào đó','To a certain extent, I agree with this view.','Ở một mức độ nào đó, tôi đồng ý với quan điểm này.','phr','approved','SteelSpeak',138),
((select id from public.tracks where slug='ielts65'),'It goes without saying that','Hiển nhiên là','It goes without saying that health is important.','Hiển nhiên là sức khỏe rất quan trọng.','phr','approved','SteelSpeak',139),
((select id from public.tracks where slug='ielts65'),'In the long run','Về lâu dài','In the long run, renewable energy is cheaper.','Về lâu dài, năng lượng tái tạo rẻ hơn.','phr','approved','SteelSpeak',140),
((select id from public.tracks where slug='ielts65'),'Taking everything into account','Xét mọi yếu tố','Taking everything into account, the benefits outweigh the drawbacks.','Xét mọi yếu tố, lợi ích lớn hơn tác hại.','phr','approved','SteelSpeak',141),
((select id from public.tracks where slug='ielts65'),'To be honest','Thành thật mà nói','To be honest, I rarely take the bus.','Thành thật mà nói, tôi hiếm khi đi xe buýt.','phr','approved','SteelSpeak',142),
